import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useState, type FormEvent } from "react";
import { Shell } from "@/components/shell";
import { Button, Field, inputClass, cx, joinLink } from "@/components/ui";
import { QrCode } from "@/components/qr-code";
import { ensureSession, supabase } from "@/lib/supabase";

/**
 * Create-room page. Lists active games from Supabase, then creates a room for
 * the chosen game and adds the visitor as host. The room code is generated by
 * the database trigger, so it's read back from the inserted row.
 */
export const Route = createFileRoute("/play")({
  validateSearch: (search: Record<string, unknown>) => ({
    game: typeof search.game === "string" ? search.game : "",
  }),
  head: () => ({ meta: [{ title: "إنشاء غرفة — العش" }] }),
  component: CreatePage,
});

type GameRow = {
  id: string;
  slug: string;
  title_ar: string;
  description_ar: string;
  min_players: number;
  max_players: number;
};

type RoomRow = {
  id: string;
  room_code: string;
  game_id: string;
  status: string;
};

type PlayerRow = {
  id: string;
  player_name: string;
  is_host: boolean;
};

function CreatePage() {
  const { game: preselected } = Route.useSearch();
  const [games, setGames] = useState<GameRow[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  // The URL carries a game slug (e.g. tactical-grid). Selection uses the row id.
  const [selected, setSelected] = useState<string>("");
  const [hostName, setHostName] = useState("");
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [room, setRoom] = useState<RoomRow | null>(null);
  const [players, setPlayers] = useState<PlayerRow[]>([]);
  const [starting, setStarting] = useState(false);
  const [startError, setStartError] = useState<string | null>(null);

  // When the page opens with ?game=<slug>, select that game once the list is loaded.
  useEffect(() => {
    if (!games || !preselected) return;
    const match = games.find((g) => g.slug === preselected);
    if (match) setSelected(match.id);
  }, [games, preselected]);

  // Load the active games (public read per RLS).
  useEffect(() => {
    if (!supabase) {
      setLoadError("الاتصال بقاعدة البيانات غير مضبوط بعد.");
      return;
    }
    supabase
      .from("games")
      .select("id, slug, title_ar, description_ar, min_players, max_players")
      .eq("is_active", true)
      .order("title_ar")
      .then(({ data, error }) => {
        if (error) setLoadError("تعذّر تحميل الألعاب، حاول مرة أخرى.");
        else setGames((data ?? []) as GameRow[]);
      });
  }, []);

  // Once a room exists, keep its player list live. Any insert, update or delete
  // on this room's players triggers a fresh read, which respects RLS.
  useEffect(() => {
    if (!supabase || !room) return;
    const client = supabase;
    const roomId = room.id;
    let cancelled = false;

    async function loadPlayers() {
      const { data } = await client
        .from("room_players")
        .select("id, player_name, is_host")
        .eq("room_id", roomId)
        .order("joined_at");
      if (!cancelled) setPlayers((data ?? []) as PlayerRow[]);
    }

    loadPlayers();
    const channel = client
      .channel(`room-players-${roomId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "room_players", filter: `room_id=eq.${roomId}` },
        () => {
          loadPlayers();
        },
      )
      .subscribe();

    return () => {
      cancelled = true;
      client.removeChannel(channel);
    };
  }, [room]);

  // Keep the room status live, so the host sees changes made from anywhere.
  useEffect(() => {
    if (!supabase || !room) return;
    const client = supabase;
    const roomId = room.id;
    const channel = client
      .channel(`room-status-${roomId}`)
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "game_rooms", filter: `id=eq.${roomId}` },
        (payload) => {
          const next = (payload.new as { status?: string }).status;
          if (next) setRoom((current) => (current ? { ...current, status: next } : current));
        },
      )
      .subscribe();

    return () => {
      client.removeChannel(channel);
    };
  }, [room?.id]);

  async function startGame() {
    if (!supabase || !room) return;
    setStartError(null);
    setStarting(true);
    try {
      // Only the host can change the room (RLS). Only a lobby can be started.
      const { data, error } = await supabase
        .from("game_rooms")
        .update({ status: "playing" })
        .eq("id", room.id)
        .eq("status", "lobby")
        .select("status")
        .maybeSingle();
      if (error) throw error;
      if (!data) return setStartError("لم تبدأ اللعبة. ربما بدأت بالفعل، حدّث الصفحة.");
      setRoom((current) => (current ? { ...current, status: "playing" } : current));
    } catch {
      setStartError("تعذّر بدء اللعبة، حاول مرة أخرى.");
    } finally {
      setStarting(false);
    }
  }

  async function createRoom(event: FormEvent) {
    event.preventDefault();
    setFormError(null);
    const name = hostName.trim().replace(/\s+/g, " ");
    if (!selected) return setFormError("اختر لعبة أولاً.");
    if (name.length < 2 || name.length > 24) return setFormError("الاسم بين حرفين و24 حرفًا.");
    if (!supabase) return setFormError("الاتصال بقاعدة البيانات غير مضبوط بعد.");

    setBusy(true);
    try {
      const session = await ensureSession();
      const userId = session.user.id;

      // 1) Create the room. Its code is generated by the database trigger.
      const { data: created, error: roomError } = await supabase
        .from("game_rooms")
        .insert({ game_id: selected, settings: {} })
        .select("id, room_code, game_id, status")
        .single();
      if (roomError || !created) throw roomError ?? new Error("ROOM_CREATE_FAILED");
      const newRoom = created as RoomRow;

      // 2) Add the visitor as the host player.
      const { error: playerError } = await supabase.from("room_players").insert({
        room_id: newRoom.id,
        user_id: userId,
        player_name: name,
        is_host: true,
      });
      if (playerError) throw playerError;

      setRoom(newRoom);
    } catch (err) {
      setFormError(friendlyError(err));
    } finally {
      setBusy(false);
    }
  }

  if (room) {
    return (
      <Shell>
        <section className="glass-card mx-auto mt-6 max-w-xl rounded-3xl p-6 text-center">
          <p className="text-sm text-muted">رمز الغرفة</p>
          <p className="mt-2 font-mono text-4xl font-extrabold tracking-[0.3em] text-neon">{room.room_code}</p>
          <p className="mt-3 text-sm text-muted">شارك الرمز مع اللاعبين ليدخلوا من جوالاتهم.</p>

          <div className="mt-5 flex flex-col items-center gap-3">
            <QrCode text={joinLink(room.room_code)} className="size-44" />
            <p className="text-xs text-muted">امسح الـ QR من الجوال، أو افتح الرابط:</p>
            <a href={joinLink(room.room_code)} className="break-all text-sm font-bold text-neon underline-offset-4 hover:underline">
              {joinLink(room.room_code)}
            </a>
          </div>

          {room.status === "playing" ? (
            <div className="mt-6 space-y-3">
              <p className="rounded-2xl border border-emerald/40 bg-emerald/10 p-4 text-sm font-bold text-ivory">
                بدأت اللعبة. تابع الشاشة الكبيرة.
              </p>
              <Link
                to="/host/$code"
                params={{ code: room.room_code }}
                className="inline-flex min-h-11 w-full items-center justify-center rounded-full bg-neon px-5 text-sm font-bold text-night"
              >
                افتح شاشة المضيف
              </Link>
            </div>
          ) : (
            <div className="mt-6">
              {(() => {
                const game = games?.find((g) => g.id === room.game_id);
                const min = game?.min_players ?? 2;
                const max = game?.max_players ?? 12;
                const enough = players.length >= min;
                return (
                  <>
                    <p className="text-sm text-muted">
                      {enough ? "جاهزون للبدء." : `تحتاج ${min} لاعبين على الأقل للبدء.`} الحد الأقصى {max}.
                    </p>
                    {startError ? <p className="mt-2 text-sm text-crimson">{startError}</p> : null}
                    <Button
                      type="button"
                      tone="primary"
                      className="mt-3 w-full"
                      disabled={!enough || starting}
                      onClick={startGame}
                    >
                      {starting ? "جارٍ البدء…" : "ابدأ اللعبة"}
                    </Button>
                  </>
                );
              })()}
            </div>
          )}

          <h2 className="mt-6 text-right text-base font-extrabold text-ivory">اللاعبون ({players.length})</h2>
          <ul className="mt-2 space-y-2 text-right">
            {players.map((p) => (
              <li key={p.id} className="flex items-center justify-between rounded-xl bg-white/[0.04] px-4 py-2 text-sm">
                <span className="text-ivory">{p.player_name}</span>
                {p.is_host ? <span className="text-xs font-bold text-violet">المضيف</span> : null}
              </li>
            ))}
          </ul>

          <Link to="/" className="mt-6 inline-flex min-h-11 items-center rounded-full border border-white/15 px-5 text-sm font-bold text-ivory">
            العودة للرئيسية
          </Link>
        </section>
      </Shell>
    );
  }

  return (
    <Shell>
      <section className="mx-auto mt-6 max-w-3xl">
        <h1 className="text-2xl font-extrabold text-ivory">إنشاء غرفة</h1>
        <p className="mt-2 text-sm text-muted">اختر اللعبة، واكتب اسمك، ثم افتح الغرفة.</p>

        {loadError ? (
          <p className="mt-6 rounded-2xl border border-crimson/40 bg-crimson/10 p-4 text-sm text-ivory">{loadError}</p>
        ) : games === null ? (
          <p className="mt-6 text-sm text-muted">جارٍ تحميل الألعاب…</p>
        ) : (
          <form onSubmit={createRoom} className="mt-6 space-y-6">
            <div className="grid gap-3 sm:grid-cols-2">
              {games.map((g) => (
                <button
                  key={g.id}
                  type="button"
                  onClick={() => setSelected(g.id)}
                  aria-pressed={selected === g.id}
                  className={cx(
                    "glass-card rounded-2xl p-4 text-right transition",
                    selected === g.id ? "border-neon/70 shadow-[0_0_0_3px_rgb(6_182_212/0.15)]" : "hover:border-neon/40",
                  )}
                >
                  <span className="block text-base font-extrabold text-ivory">{g.title_ar}</span>
                  <span className="mt-1 block text-sm leading-6 text-muted">{g.description_ar}</span>
                  <span className="mt-2 block text-xs font-bold text-muted">
                    👥 {g.min_players}–{g.max_players} لاعب
                  </span>
                </button>
              ))}
            </div>

            <Field label="اسمك (المضيف)">
              <input
                className={inputClass}
                value={hostName}
                onChange={(e) => setHostName(e.target.value)}
                maxLength={24}
                placeholder="اكتب اسمك"
                autoComplete="nickname"
              />
            </Field>

            {formError ? <p className="text-sm text-crimson">{formError}</p> : null}

            <Button type="submit" tone="primary" disabled={busy || !selected} className="w-full">
              {busy ? "جارٍ الإنشاء…" : "افتح الغرفة"}
            </Button>
          </form>
        )}
      </section>
    </Shell>
  );
}

function friendlyError(err: unknown): string {
  const message = err instanceof Error ? err.message : String((err as { message?: string })?.message ?? err);
  if (message.includes("SUPABASE_NOT_CONFIGURED")) return "الاتصال بقاعدة البيانات غير مضبوط بعد.";
  if (message.includes("ANON_SIGNIN_FAILED") || message.toLowerCase().includes("anonymous"))
    return "تعذّر تسجيل الدخول المؤقت. تأكد من تفعيل Anonymous Sign-Ins في Supabase.";
  if (message.includes("ROOM_FULL")) return "الغرفة ممتلئة.";
  if (message.includes("ROOM_FINISHED")) return "انتهت هذه الغرفة.";
  return "تعذّر إنشاء الغرفة، حاول مرة أخرى.";
}
